starter.css:
body {
  margin: 0;
  font-family: system-ui, sans-serif;
}

.pagina {
  width: 960px;
  margin: 0 auto;
  padding: 16px;
}

h1 {
  font-size: 32px;
}

solution.css:
body {
  margin: 0;
  font-family: system-ui, sans-serif;
}

.pagina {
  width: 100%;
  max-width: 60rem;
  margin: 0 auto;
  padding: 1rem;
}

h1 {
  font-size: 1.75rem;
}

starter.css:
.grade {
  display: flex;
  flex-wrap: wrap;
}

.coluna {
  width: 50%;
  padding: 1rem;
  box-sizing: border-box;
}

@media (min-width: 600px) {
  .grade {
    width: 960px;
  }
}

solution.css:
.grade {
  display: flex;
  flex-wrap: wrap;
}

.coluna {
  width: 100%;
  padding: 1rem;
  box-sizing: border-box;
}

@media (min-width: 600px) {
  .coluna {
    width: 50%;
  }
}

.cartao {
  width: 100%;
  max-width: 40rem;
  margin: 0 auto;
}

.foto {
  display: block;
  max-width: 100%;
  height: auto;
}
